class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        was_training = self.view.model.training
        metrics, definitions = {}, {}
        try:
            self.view.model.eval()
            with no_grad():
                for prefix in fixed_observed_training_prefixes(self.view.user_train):
                    candidates = fixed_eligible_candidates(prefix)
                    baseline = score_with_view(prefix, candidates)
                    groups = identify_recent_recurrent_isolated(prefix)
                    for group in groups:
                        k = predefined_feasible_subset_size(group, prefix)
                        if k is insufficient:
                            record_unavailable(group)
                            continue
                        controls = seeded_random_subsets(prefix, k)
                        for operation in supported_operations:
                            targeted = score_with_view(operation(prefix, group, k), candidates)
                            random_results = [score_with_view(operation(prefix, subset, k), candidates)
                                              for subset in controls]
                            record_paired_rank_changes(baseline, targeted, random_results)
                metrics = aggregate_with_counts_and_history_length_slices()
                definitions = describe_metrics_controls_and_missingness()
        finally:
            self.view.model.train(was_training)
        return {'metrics': metrics, 'metric_definitions': definitions}
